import sys

class Node:
    __slots__ = ('value', 'prev', 'next')
    def __init__(self, value):
        self.value = value
        self.prev = None
        self.next = None

def main():
    input = sys.stdin.read().splitlines()
    n = int(input[0])
    commands = input[1:n+1]

    head = None
    tail = None

    for cmd in commands:
        parts = cmd.split()
        if parts[0] == 'insert':
            x = int(parts[1])
            new_node = Node(x)
            if head is None:
                head = new_node
                tail = new_node
            else:
                new_node.next = head
                head.prev = new_node
                head = new_node
        elif parts[0] == 'delete':
            x = int(parts[1])
            current = head
            while current is not None:
                if current.value == x:
                    # Delete the node
                    if current.prev:
                        current.prev.next = current.next
                    else:
                        # current is head
                        head = current.next
                    if current.next:
                        current.next.prev = current.prev
                    else:
                        # current is tail
                        tail = current.prev
                    break
                current = current.next
        elif parts[0] == 'deleteFirst':
            if head is not None:
                if head.next is not None:
                    head.next.prev = None
                else:
                    # Only one node
                    tail = None
                head = head.next
        elif parts[0] == 'deleteLast':
            if tail is not None:
                if tail.prev is not None:
                    tail.prev.next = None
                else:
                    # Only one node
                    head = None
                tail = tail.prev

    # Collect the elements
    result = []
    current = head
    while current is not None:
        result.append(str(current.value))
        current = current.next
    print(' '.join(result))

if __name__ == '__main__':
    main()

